from full_a import cat, C

cat("friends", "Friends of Jesus", "The people who walked with Him.", "martha", [
 dict(id="mary-magdalene", name="Mary Magdalene", role="The first person to see Jesus risen", art="magdalene",
  facts=["From Magdala", "Freed from seven demons", "First witness of Easter"], cards=[
  C("Set free", "Mary came from Magdala, a fishing town on the Sea of Galilee. Jesus drove seven demons out of her.",
    "Luke names her first among several women Jesus had healed who traveled with Him and the twelve, supporting them out of their own money. She is often confused with the sinful woman who anointed Jesus’ feet, but the Bible never says that was her.", ("Luke",8)),
  C("She stayed", "When most of the disciples fled, Mary Magdalene stood near the cross, then watched where Jesus was buried.",
    "All four Gospels place her at the crucifixion. She saw Joseph of Arimathea and Nicodemus lay the body in the tomb and roll the stone across, and went home to prepare spices for after the Sabbath.", ("John",19)),
  C("The empty tomb", "Before dawn on Sunday she found the stone rolled away and ran to tell Peter and John.",
    "She assumed someone had taken the body: “They have taken the Lord out of the tomb, and we don’t know where they have put Him!” Peter and John ran, looked, and went home. Mary stayed outside, crying.", ("John",20)),
  C("“Mary!”", "She mistook the risen Jesus for the gardener — until He said her name. She was the first person to see Him alive.",
    "Two angels asked why she was crying. She turned and saw a man she thought was the gardener: “Sir, if you have carried Him away, tell me where.” Jesus said, “Mary.” She cried out, “Rabboni!” (Teacher). He sent her to tell the disciples: “I am ascending to My Father and your Father.” She went and announced, “I have seen the Lord!” — earning her the ancient title “apostle to the apostles.”", ("John",20)),
 ]),
 dict(id="martha-mary", name="Martha & Mary of Bethany", role="Two sisters — one busy, one listening", art="martha",
  facts=["Lived in Bethany", "Sisters of Lazarus", "Jesus’ close friends"], cards=[
  C("An open home", "Martha, Mary and their brother Lazarus lived in Bethany, two miles from Jerusalem. Jesus often stayed with them.",
    "John says simply, “Jesus loved Martha and her sister and Lazarus.” Their home was a place of rest for Him during visits to Jerusalem.", ("John",11)),
  C("Busy vs. listening", "Martha rushed to make dinner while Mary sat at Jesus’ feet. Jesus said Mary had chosen the one thing that mattered.",
    "Sitting at a teacher’s feet was the posture of a disciple — unusual for a woman then. Martha, overwhelmed, asked Jesus to tell Mary to help. He answered gently, “Martha, Martha, you are worried and upset about many things, but few things are needed — or indeed only one. Mary has chosen what is better, and it will not be taken from her.”", ("Luke",10)),
  C("“If You had been here…”", "When Lazarus died, both sisters said the same words to Jesus. To Martha He said, “I am the resurrection and the life.”",
    "Martha went out to meet Jesus and said, “Lord, if You had been here, my brother would not have died. But I know that even now God will give You whatever You ask.” Jesus said, “I am the resurrection and the life. Whoever believes in Me will live, even though they die. Do you believe this?” Martha answered, “Yes, Lord. I believe that You are the Messiah, the Son of God.” Mary came and fell at His feet weeping, and Jesus wept with her. Then He raised Lazarus.", ("John",11)),
  C("The perfume", "Six days before Passover, Mary poured a pint of expensive perfume on Jesus’ feet and wiped them with her hair.",
    "The nard was worth about a year’s wages. The house filled with the fragrance. Judas complained; Jesus said, “Leave her alone. She has kept this for the day of My burial.” Martha, true to form, was serving the dinner.", ("John",12)),
 ]),
 dict(id="lazarus", name="Lazarus", role="The man Jesus raised after four days in the tomb", art=None,
  facts=["From Bethany", "Brother of Martha & Mary", "Dead four days"], cards=[
  C("“The one You love is sick”", "Lazarus fell seriously ill. His sisters sent word to Jesus. Jesus waited two more days.",
    "Jesus said the sickness would not end in death but was for God’s glory. Then He told the disciples, “Our friend Lazarus has fallen asleep, but I am going there to wake him up.” They thought He meant actual sleep, so He told them plainly, “Lazarus is dead.”", ("John",11)),
  C("Jesus wept", "When Jesus arrived, Lazarus had been in the tomb four days. Seeing everyone grieving, Jesus wept.",
    "Jewish belief held that the soul lingered near the body for three days — four days meant hopelessly dead. Jesus was deeply moved and troubled. “Jesus wept” is the shortest verse in most English Bibles. The onlookers said, “See how He loved him!”", ("John",11)),
  C("“Lazarus, come out!”", "Jesus had the stone removed, prayed, and shouted. Lazarus walked out, still wrapped in grave cloths.",
    "Martha warned, “By this time there is a bad odor.” Jesus said, “Did I not tell you that if you believe, you will see the glory of God?” He thanked the Father aloud so the crowd would believe, then called in a loud voice. Jesus said, “Take off the grave clothes and let him go.”", ("John",11)),
  C("A marked man", "Many believed because of Lazarus. The chief priests plotted to kill Jesus — and Lazarus too.",
    "From that day the council planned Jesus’ death. Crowds came to Bethany just to see Lazarus, so the chief priests made plans to kill him as well, because on account of him many were believing in Jesus. A week later Lazarus was at the dinner where Mary anointed Jesus.", ("John",12)),
 ]),
 dict(id="nicodemus", name="Nicodemus", role="The religious leader who came to Jesus at night", art=None,
  facts=["A Pharisee", "Member of the ruling council", "Helped bury Jesus"], cards=[
  C("A visit at night", "Nicodemus, a leading Pharisee, came to Jesus secretly at night: “We know You are a teacher who has come from God.”",
    "He was a member of the Sanhedrin, the 71-member Jewish ruling council, and Jesus called him “Israel’s teacher.” Coming at night likely kept the visit hidden from his colleagues.", ("John",3)),
  C("Born again", "Jesus told him, “No one can see the kingdom of God unless they are born again.” Then He said John 3:16.",
    "Nicodemus took it literally: “How can someone be born when they are old?” Jesus explained a birth of water and the Spirit. Then: “For God so loved the world that He gave His one and only Son, that whoever believes in Him shall not perish but have eternal life.”", ("John",3)),
  C("Speaking up", "When the council wanted Jesus arrested, Nicodemus objected: “Does our law condemn a man without hearing him?”",
    "The others mocked him: “Are you from Galilee too?” It was a small, risky step into the open.", ("John",7)),
  C("Burying Jesus", "After the crucifixion, Nicodemus brought about 75 pounds of myrrh and aloes and helped bury Jesus.",
    "That amount of spices was fit for a king’s burial. With Joseph of Arimathea he wrapped the body in linen and laid it in a new tomb. The man who came in the dark now stepped forward publicly — at the moment the disciples were hiding.", ("John",19)),
 ]),
 dict(id="zacchaeus", name="Zacchaeus", role="The short tax collector who climbed a tree", art=None,
  facts=["Chief tax collector in Jericho", "Very rich", "Very short"], cards=[
  C("Rich and hated", "Zacchaeus was the chief tax collector in Jericho — wealthy from cheating his own people.",
    "Jericho was a wealthy trade city on the road to Jerusalem. As chief tax collector he oversaw other collectors and profited from all of them. His name ironically means “pure” or “innocent.”", ("Luke",19)),
  C("Up a tree", "Too short to see over the crowd, he ran ahead and climbed a sycamore-fig tree to see Jesus.",
    "Grown men of rank didn’t run or climb trees. Zacchaeus didn’t care how it looked.", ("Luke",19)),
  C("“Hurry down”", "Jesus stopped, looked up, and called him by name: “I must stay at your house today.” The crowd grumbled.",
    "Of all the people in Jericho, Jesus chose to be the guest of the most despised man there. Zacchaeus came down at once and welcomed Him gladly. Everyone muttered, “He has gone to be the guest of a sinner.”", ("Luke",19)),
  C("A changed man", "Zacchaeus promised to give half his wealth to the poor and repay anyone he’d cheated four times over.",
    "The law only required repaying the amount plus a fifth. Jesus said, “Today salvation has come to this house… For the Son of Man came to seek and to save the lost.”", ("Luke",19)),
 ]),
])

cat("church", "The Early Church", "How a small group in Jerusalem spread the news everywhere.", "stephen", [
 dict(id="paul", name="Paul", role="Persecutor turned the greatest missionary", art="paul-prison",
  facts=["Also called Saul", "Wrote 13 letters", "Traveled about 10,000 miles"], cards=[
  C("Saul of Tarsus", "Saul was a brilliant, strict Pharisee from Tarsus, trained in Jerusalem under the famous teacher Gamaliel. He was also a Roman citizen.",
    "He described himself as “a Hebrew of Hebrews… as for zeal, persecuting the church; as for righteousness based on the law, faultless.” He made tents for a living. Saul was his Hebrew name; Paul was his Roman one.", ("Philippians",3)),
  C("Hunting Christians", "Saul approved Stephen’s stoning, then went house to house dragging believers to prison.",
    "He held the coats of the men who stoned Stephen. Then he got letters from the high priest to arrest followers of “the Way” in Damascus and bring them back to Jerusalem in chains.", ("Acts",8)),
  C("The Damascus road", "A blinding light knocked him down. “Saul, Saul, why do you persecute Me?” “Who are You, Lord?” “I am Jesus.”",
    "Saul was blind for three days and didn’t eat or drink. God sent a disciple named Ananias — terrified, because of Saul’s reputation — to lay hands on him. Something like scales fell from his eyes, he was baptized, and immediately began preaching in the synagogues that Jesus is the Son of God. His former allies plotted to kill him, and he escaped Damascus lowered in a basket through a window in the city wall.", ("Acts",9)),
  C("Barnabas vouches for him", "In Jerusalem, the disciples were afraid of him. Barnabas brought him to the apostles and told his story.",
    "Paul spent years in Arabia, Damascus and his hometown of Tarsus. Later Barnabas went to find him and brought him to Antioch, where the believers were first called Christians.", ("Acts",9)),
  C("Missionary journeys", "Paul made three long journeys around the Mediterranean, starting churches in cities like Philippi, Corinth and Ephesus.",
    "He usually started in the local synagogue, then reached Gentiles. In Lystra he was stoned and left for dead, then got up and went back into the city. In Athens he preached on Mars Hill about “the unknown god.” In Ephesus a riot broke out because the silversmiths who made idols were losing business. He worked making tents so he wouldn’t be a burden.", ("Acts",17)),
  C("Singing in prison", "In Philippi, Paul and Silas were beaten and locked in stocks. At midnight they sang hymns — and an earthquake opened every door.",
    "They had freed a slave girl from a spirit that let her owners make money telling fortunes. The jailer woke, saw the doors open, and was about to kill himself, thinking the prisoners had escaped. Paul shouted, “Don’t harm yourself! We are all here!” The jailer asked, “What must I do to be saved?” “Believe in the Lord Jesus.” He and his whole household were baptized that night.", ("Acts",16)),
  C("What he suffered", "Paul was flogged five times, beaten with rods three times, stoned once, and shipwrecked three times.",
    "He lists it himself: “in danger from rivers, bandits, my own people, Gentiles… I have known hunger and thirst… I have been cold and naked.” He also had a “thorn in the flesh” God didn’t remove, and heard God say, “My grace is sufficient for you, for My power is made perfect in weakness.”", ("2 Corinthians",11)),
  C("His letters", "Paul wrote 13 letters in the New Testament — more than any other writer — to churches and friends.",
    "Romans explains salvation by grace through faith. 1 Corinthians 13 says, “Love is patient, love is kind.” Philippians, written from prison, says, “Rejoice in the Lord always,” and “I can do all things through Christ who strengthens me.” Galatians says, “There is neither Jew nor Gentile, slave nor free, male nor female, for you are all one in Christ Jesus.”", ("Romans",8)),
  C("Arrested and shipwrecked", "Paul was arrested in Jerusalem, appealed to Caesar, and was shipwrecked on Malta on the way to Rome.",
    "A mob in the Temple nearly killed him. He spent two years in custody in Caesarea, testifying before governors and King Agrippa. As a Roman citizen he appealed to the emperor. On the voyage a storm raged for two weeks; Paul told all 276 on board that an angel promised no one would die. The ship broke apart off Malta, and everyone made it to shore. A snake bit him and he was unharmed.", ("Acts",27)),
  C("How it ended", "Paul spent two years under house arrest in Rome, still preaching. Early church tradition says he was beheaded under Nero.",
    "Acts ends with Paul in Rome “proclaiming the kingdom of God… with all boldness and without hindrance.” His last letter, to Timothy, says, “I have fought the good fight, I have finished the race, I have kept the faith.” Clement of Rome and later writers record his martyrdom in Rome around AD 64–67. As a citizen he would have been beheaded rather than crucified.", ("2 Timothy",4)),
 ]),
 dict(id="stephen", name="Stephen", role="The first Christian to die for Jesus", art="stephen",
  facts=["One of seven helpers", "Full of the Spirit", "Forgave his killers"], cards=[
  C("Chosen to serve", "When Greek-speaking widows were overlooked in the daily food handout, the apostles chose seven men to serve. Stephen was first.",
    "The requirement was men “full of the Spirit and wisdom.” Stephen is described as “full of faith and of the Holy Spirit” and “full of God’s grace and power,” performing great wonders and signs.", ("Acts",6)),
  C("Falsely accused", "Opponents couldn’t win arguments with him, so they paid men to lie that he spoke against Moses and the Temple.",
    "He was dragged before the Sanhedrin. As they stared at him, they saw his face was like the face of an angel.", ("Acts",6)),
  C("His great speech", "Stephen retold Israel’s history — Abraham, Joseph, Moses — showing the people had always rejected God’s messengers.",
    "It’s the longest speech in Acts. He ended: “You stiff-necked people! You always resist the Holy Spirit… You have received the law but have not obeyed it.” The council was furious.", ("Acts",7)),
  C("How it ended", "He saw heaven open and Jesus standing at God’s right hand. They dragged him out and stoned him. He prayed for his killers.",
    "He cried, “Lord Jesus, receive my spirit,” then knelt and said, “Lord, do not hold this sin against them.” A young man named Saul stood guarding the coats. Stephen’s death triggered a persecution that scattered believers — who spread the message everywhere they went.", ("Acts",7)),
 ]),
 dict(id="barnabas", name="Barnabas", role="“Son of Encouragement”", art=None,
  facts=["Gave away his land", "Vouched for Paul", "Missionary partner"], cards=[
  C("The encourager", "His name was Joseph, a Levite from Cyprus, but the apostles called him Barnabas — “son of encouragement.” He sold a field and gave the money away.",
    "He laid the money at the apostles’ feet to help believers in need. Acts calls him “a good man, full of the Holy Spirit and faith.”", ("Acts",4)),
  C("Taking a chance on Paul", "Everyone in Jerusalem was afraid of the former persecutor. Barnabas brought Paul to the apostles and vouched for him.",
    "Later, when the church in Antioch was growing, Barnabas went to Tarsus to find Paul and brought him to help. They taught there for a year.", ("Acts",11)),
  C("The first missionary journey", "Barnabas and Paul were sent out together to Cyprus and Asia Minor. In Lystra, the crowd thought they were gods.",
    "After Paul healed a lame man, the people shouted that the gods had come down — calling Barnabas Zeus and Paul Hermes — and tried to offer sacrifices. The two tore their clothes and begged them to turn to the living God.", ("Acts",14)),
  C("A second chance for Mark", "When Paul refused to take John Mark again, Barnabas split with Paul and took Mark anyway.",
    "Mark had quit the first trip. Barnabas, his cousin, wouldn’t give up on him. Years later Paul wrote, “Get Mark and bring him with you, because he is helpful to me.” Mark wrote the Gospel of Mark.", ("Acts",15)),
 ]),
 dict(id="timothy", name="Timothy", role="Paul’s young protégé", art=None,
  facts=["Raised by mom & grandma in faith", "Pastor in Ephesus", "Got two letters from Paul"], cards=[
  C("Sincere faith", "Timothy grew up in Lystra. His Jewish mother Eunice and grandmother Lois taught him the Scriptures from childhood.",
    "His father was Greek. Paul wrote, “I am reminded of your sincere faith, which first lived in your grandmother Lois and in your mother Eunice.”", ("2 Timothy",1)),
  C("Joining Paul", "On his second journey Paul took young Timothy along. He became Paul’s most trusted helper.",
    "Paul called him “my true son in the faith” and sent him to strengthen churches in Thessalonica, Corinth and Philippi. Six of Paul’s letters name Timothy as co-sender.", ("Acts",16)),
  C("Letters to a young pastor", "Leading the church in Ephesus, Timothy received two letters from Paul: “Don’t let anyone look down on you because you are young.”",
    "Paul told him to set an example in speech, life, love, faith and purity, and that “God did not give us a spirit of fear, but of power, love and self-discipline.” Paul’s last letter, written from prison near his death, begs Timothy to come quickly.", ("1 Timothy",4)),
 ]),
 dict(id="lydia", name="Lydia", role="Businesswoman and the first Christian in Europe", art=None,
  facts=["Sold purple cloth", "From Thyatira", "Opened her home"], cards=[
  C("A dealer in purple", "Lydia, from Thyatira, sold expensive purple cloth in Philippi. She worshiped God and prayed by the river on the Sabbath.",
    "Purple dye was costly and associated with royalty, so her business served the wealthy. Philippi didn’t have enough Jewish men for a synagogue, so worshipers met by the river.", ("Acts",16)),
  C("Her heart opened", "When Paul spoke to the women there, “the Lord opened her heart.” She and her household were baptized — the first recorded converts in Europe.",
    "She insisted Paul and his companions stay at her home. After Paul and Silas were freed from prison, they went to Lydia’s house, where the believers met. Her home became the first church in Philippi.", ("Acts",16)),
 ]),
 dict(id="priscilla-aquila", name="Priscilla & Aquila", role="A married couple who served together", art=None,
  facts=["Tentmakers", "Hosted a church at home", "Taught Apollos"], cards=[
  C("Refugees and tentmakers", "Aquila and Priscilla were Jewish tentmakers expelled from Rome by Emperor Claudius. In Corinth, Paul worked in their shop.",
    "The Roman historian Suetonius records Claudius expelling Jews from Rome around AD 49. Paul shared their trade and lived with them for 18 months.", ("Acts",18)),
  C("Teaching a teacher", "When gifted preacher Apollos was missing part of the story of Jesus, they invited him home and explained it more fully.",
    "They did it privately and graciously. Apollos went on to be a powerful leader in Corinth.", ("Acts",18)),
  C("Risking their necks", "Paul said they risked their lives for him, and hosted churches in their home in Ephesus and Rome.",
    "Paul writes, “Greet Priscilla and Aquila, my co-workers in Christ Jesus. They risked their lives for me… Greet also the church that meets at their house.” Priscilla is usually named first — unusual then, and perhaps a sign of her leadership.", ("Romans",16)),
 ]),
])
